extern alias game;
using System.Text.Json;
internal static class BoardFactionTest
{
    private sealed class Peer : IDisposable
    {
        private readonly System.Net.Sockets.TcpClient socket=new();private readonly WireCodec codec;public SessionKeyInfo Key=new();public byte[] Last=[];
        public Peer(string root){codec=new(JsonSerializer.Deserialize<int[]>(File.ReadAllText(Path.Combine(root,"LocalServer/data/packet-keys.json")))!);}
        private async Task<(ushort,byte[])> Send(System.Net.Sockets.TcpClient client,ushort command,object request){await client.GetStream().WriteAsync(codec.Encode(command,WireCodec.Serialize(request),true));using var timeout=new CancellationTokenSource(10000);var r=codec.Decode((await WireCodec.ReadFrame(client.GetStream(),timeout.Token))!,true);return(r.Command,r.Payload);}
        public async Task Login(LocalRuntime server){using var login=new System.Net.Sockets.TcpClient();await login.ConnectAsync("127.0.0.1",server.LoginPort);await Send(login,(ushort)LoginServerCommand.LS_LOGIN_REQUEST,new LsLoginRequest{userID="local-player",userPW="local",osType=DeviceOSType.DEVICE_PC});var start=Read<LsGameStartOk>((await Send(login,(ushort)LoginServerCommand.LS_GAME_START_REQUEST,new LsGameStartRequest{serverId=1,bAgreement=true})).Item2);Key=new(){uid=start.uid,loginSessionKey=start.loginSessionKey};await socket.ConnectAsync("127.0.0.1",server.GamePort);}
        public async Task<T> Request<T>(GameServerCommand cmd,object req,bool success=true,bool retry=false){if(!retry)Key.sequenceNo++;var r=await Send(socket,(ushort)cmd,req);string expected=cmd.ToString().Replace("_REQUEST",success?"_OK":"_FAIL");if(((GameServerCommand)r.Item1).ToString()!=expected)throw new Exception(expected+": "+Read<FailPacket>(r.Item2).message);Last=r.Item2;return Read<T>(r.Item2);}
        public void Dispose()=>socket.Dispose();
    }
    private static T Read<T>(byte[] bytes)=>(T)WireCodec.Deserialize(typeof(T),bytes)!;

    private static LocalPlayer Prepare(LocalRuntime server)
    {
        var p=server.Store.GetOrCreate("local-player");var c=server.Catalog;p.Level=99;p.Exp=ProgressionRules.PlayerFloor(c,99);p.Gold=100000000;p.CashPoint=1000000;p.Stamina=10000;
        p.CardIds=c.UsableHeroes.Where(x=>x.Rank==6).GroupBy(x=>x.EvolveFirstAncestor).Select(x=>(uint)x.First().Id).ToList();p.CollectedCardIds.UnionWith(p.CardIds);p.Deck=[1,2,3,4,5];p.Decks[9]=p.Deck.ToList();
        for(ulong seq=1;seq<=(ulong)p.CardIds.Count;seq++)p.CardStates[seq]=new(){Level=99,Exp=ProgressionRules.CardFloor(c,99),Enchant=10,ActiveSkills=[30,30],PassiveSkills=[30,30,30,30,30]};
        var data=new BoardResourceCatalog(TableExtractor.FindRoot());
        foreach(var row in data.Resources){p.Decks[(uint)row.UseDeck]=p.CardIds.Select((id,i)=>new{id,i}).Where(x=>{var card=c.Cards.Single(v=>v.Id==x.id);return (row.EnterType==BscTable.CARD_FACTION.FACTION_ALL||card.Faction==row.EnterType)&&(row.AttackType==BscTable.ATTACK_TYPE.ATTACK_ALL||card.AttackType==row.AttackType);}).Take(5).Select(x=>(ulong)x.i+1).ToList();}
        ulong day=(ProtocolRouter.Now+8*3600)/86400;p.AttendanceDays=1;p.AttendanceLastDay=day;p.AttendanceVipClaimedDay=day;p.ShortTermDays=1;p.ShortTermLastDay=day;p.Missions.DicePoints=100000;server.Store.Save();return p;
    }
    public static async Task Fixture(string root,string output)
    {
        output=Path.GetFullPath(output);string allowed=Path.GetFullPath(Path.Combine(root,"verification"))+Path.DirectorySeparatorChar;if(!output.StartsWith(allowed,StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Isolated board/resource fixture required");
        Directory.CreateDirectory(output);await using var r=new LocalRuntime(root,Path.Combine(output,"saves"),0,0,0,false);typeof(ProtocolRouter).GetField("notices",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.SetValue(r.Router,Array.Empty<string>());if(r.Store.All().Count==0)Prepare(r);
        await using var app=await DebugToolsTest.Host(r);var addresses=app.Services.GetRequiredService<Microsoft.AspNetCore.Hosting.Server.IServer>().Features.Get<Microsoft.AspNetCore.Hosting.Server.Features.IServerAddressesFeature>()!;File.WriteAllText(Path.Combine(output,"endpoints.json"),JsonSerializer.Serialize(new{directoryPort=r.DirectoryPort,debugPort=new Uri(addresses.Addresses.Single()).Port,productionSaveUsed=false}));await Task.Delay(TimeSpan.FromHours(2));
    }
    public static async Task Run(string root)
    {
        string save=Path.Combine(root,"verification/board-resource",Guid.NewGuid().ToString("N"));var checks=new List<string>();void Check(bool value,string label){if(!value)throw new Exception(label);checks.Add(label);}
        await using(var server=new LocalRuntime(root,save,0,0,0,false)) {
            using var peer=new Peer(root);await peer.Login(server);var p=Prepare(server);var catalog=new BoardResourceCatalog(root);
            string State()=>JsonSerializer.Serialize(new{p.Board,p.Resources,p.BoardReceipts,p.ResourceReceipts,p.Gold,p.CashPoint,p.Inventory,p.EquipmentItems,p.CardIds,p.Missions,p.Stamina,p.ActiveStage,p.ActiveBattleStamp});
            async Task Bad(GameServerCommand cmd,object request,string label){string before=State();await peer.Request<FailPacket>(cmd,request,false);Check(State()==before,label+" is atomic");}
            var get=new GsGetBattleBoardPlayInfoRequest{keyInfo=peer.Key};p.Level=29;await peer.Request<FailPacket>(GameServerCommand.GS_GET_BATTLE_BOARD_PLAY_INFO_REQUEST,get,false);p.Level=99;
            var opened=await peer.Request<GsGetBattleBoardPlayInfoOk>(GameServerCommand.GS_GET_BATTLE_BOARD_PLAY_INFO_REQUEST,get);Check(opened.playInfo.mapId is 903 or 1003,"Original level-99 map range");Check(opened.playInfo.defaultDicePoint==500&&opened.playInfo.additionalDicePoint==100000,"VIP daily points and mission points available together");
            var map=catalog.Boards.Single(x=>x.Id==p.Board.Map);Check(map.SpotList.All(x=>p.Board.Rewards.Length>x.SpotId&&(x.RewardId.Count==0||p.Board.Rewards[x.SpotId]<x.RewardId.Count)),"Stable valid per-spot reward previews");
            await Bad(GameServerCommand.GS_MOVE_PAWN_BATTLE_BOARD_REQUEST,new GsMovePawnBattleBoardRequest{keyInfo=peer.Key,spotId=999},"Move before cast");
            int casts=0,battles=0,branches=0;while(p.Board.Status!=BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_COMPLETE&&casts<200) {
                if(p.Board.Status==BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_DICE_WAIT){uint points=p.Board.DefaultPoints+p.Missions.DicePoints;var req=new GsCastDiceBattleBoardRequest{keyInfo=peer.Key};var rolled=await peer.Request<GsCastDiceBattleBoardOk>(GameServerCommand.GS_CAST_DICE_BATTLE_BOARD_REQUEST,req);Check(rolled.diceValue is >=1 and <=6&&p.Board.DefaultPoints+p.Missions.DicePoints==points-100,"Cast pays original 100 points");string before=State();var bytes=peer.Last.ToArray();await peer.Request<GsCastDiceBattleBoardOk>(GameServerCommand.GS_CAST_DICE_BATTLE_BOARD_REQUEST,req,retry:true);Check(State()==before&&bytes.SequenceEqual(peer.Last),"Cast retry does not charge twice");casts++;}
                if(p.Board.Status==BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_MOVE_WAIT){uint before=p.Board.Node;await Bad(GameServerCommand.GS_MOVE_PAWN_BATTLE_BOARD_REQUEST,new GsMovePawnBattleBoardRequest{keyInfo=peer.Key,spotId=uint.MaxValue},"Forged destination");await peer.Request<GsMovePawnBattleBoardOk>(GameServerCommand.GS_MOVE_PAWN_BATTLE_BOARD_REQUEST,new GsMovePawnBattleBoardRequest{keyInfo=peer.Key,spotId=p.Board.Next});Check(p.Board.Node!=before,"Legal move advances original graph");}
                if(p.Board.Status==BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_WAY_SELECT){var spot=map.SpotList.Single(x=>x.SpotId==p.Board.Node);await Bad(GameServerCommand.GS_SELECT_BATTLE_BOARD_WAY_REQUEST,new GsSelectBattleBoardWayRequest{keyInfo=peer.Key,spotId=uint.MaxValue},"Forged branch");await peer.Request<GsSelectBattleBoardWayOk>(GameServerCommand.GS_SELECT_BATTLE_BOARD_WAY_REQUEST,new GsSelectBattleBoardWayRequest{keyInfo=peer.Key,spotId=(uint)spot.SecondNextSpotId});branches++;}
                if(p.Board.Status==BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_BATTLE){var enemy=await peer.Request<GsGetBattleBoardCardInfoOk>(GameServerCommand.GS_GET_BATTLE_BOARD_ENEMY_INFO_REQUEST,new GsGetBattleBoardEnemyInfoRequest{keyInfo=peer.Key});Check(enemy.battleEnemyInfo.cardInfoList.Count==5,"Five native guardian cards");await Bad(GameServerCommand.GS_BATTLE_BOARD_END_CONFIRM_REQUEST,new GsBattleBoardEndConfirmRequest{keyInfo=peer.Key,endType=NormalBattleEndType.NORMAL_BATTLE_SUCCESS},"Unstarted board settlement");await peer.Request<GsGetBattleBoardPlayInfoOk>(GameServerCommand.GS_BATTLE_BOARD_START_REQUEST,new GsBattleBoardStartRequest{keyInfo=peer.Key});uint points=p.Missions.DicePoints;var end=new GsBattleBoardEndConfirmRequest{keyInfo=peer.Key,endType=NormalBattleEndType.NORMAL_BATTLE_SUCCESS,battleEndSyncData=new()};await peer.Request<GsBattleBoardEndConfirmOk>(GameServerCommand.GS_BATTLE_BOARD_END_CONFIRM_REQUEST,end);Check(p.Missions.DicePoints==points+300,"Original victory dice bonus");string before=State();await peer.Request<GsBattleBoardEndConfirmOk>(GameServerCommand.GS_BATTLE_BOARD_END_CONFIRM_REQUEST,end,retry:true);Check(before==State(),"Board result retry grants once");battles++;}
            }
            Check(p.Board.Completed.Contains(p.Board.Map)&&p.Board.Status==BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_COMPLETE,"Native board can reach end and save completion");
            Check(p.Missions.Counters.GetValueOrDefault(game::BscTable.CHECK_TYPE.MCT_CAST_BATTLE_BOARD_DICE)==casts,"Mission progress counts actual casts once");
            // Force edge states independently of the random walk above.
            var branch=map.SpotList.First(x=>x.SecondNextSpotId!=0);p.Board.Node=(uint)branch.SpotId;p.Board.Status=BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_WAY_SELECT;p.Board.Next=0;
            await peer.Request<GsSelectBattleBoardWayOk>(GameServerCommand.GS_SELECT_BATTLE_BOARD_WAY_REQUEST,new GsSelectBattleBoardWayRequest{keyInfo=peer.Key,spotId=(uint)branch.SecondNextSpotId});Check(p.Board.Next==branch.SecondNextSpotId&&p.Board.Status==BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_DICE_WAIT,"Both branch routes are validated independently of random landing");
            var fight=map.SpotList.First(x=>(int)x.BattleSpotType is >=4 and <=6);p.Board.Node=(uint)fight.SpotId;p.Board.Next=(uint)fight.FirstNextSpotId;p.Board.Status=BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_BATTLE;p.Board.Enemy=null;
            var guard=await peer.Request<GsGetBattleBoardCardInfoOk>(GameServerCommand.GS_GET_BATTLE_BOARD_ENEMY_INFO_REQUEST,new GsGetBattleBoardEnemyInfoRequest{keyInfo=peer.Key});Check(guard.playInfo.lastFactionLimit==(uint)BscTable.CARD_FACTION.FACTION_ALL,"Board unrestricted faction is explicit in the native deck label");server.Store.Save();var saved=new PlayerStore(save,server.Catalog).All().Single();Check(saved.Board.Enemy?.cardInfoList.Count==5,"Guardian snapshot survives JSON save/reload");
            var beginFight=new GsBattleBoardStartRequest{keyInfo=peer.Key};await peer.Request<GsGetBattleBoardPlayInfoOk>(GameServerCommand.GS_BATTLE_BOARD_START_REQUEST,beginFight);var defeat=new GsBattleBoardEndConfirmRequest{keyInfo=peer.Key,endType=NormalBattleEndType.NORMAL_BATTLE_FAIL};await peer.Request<GsBattleBoardEndConfirmOk>(GameServerCommand.GS_BATTLE_BOARD_END_CONFIRM_REQUEST,defeat);Check(p.Board.Status==BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_BATTLE&&p.ActiveStage==null,"Defeat leaves the same battle spot available for retry");
            await Bad(GameServerCommand.GS_BATTLE_BOARD_END_CONFIRM_REQUEST,defeat,"Second new result without an active battle");
            foreach(var original in catalog.Boards.Where(x=>x.FirstRewardIdType!=BscTable.REWARD_TYPE.REWARD_NONE)) {
                p.Board.Map=(uint)original.Id;p.Board.Rewards=new byte[original.SpotList.Max(x=>x.SpotId)+1];var goal=original.SpotList.Last();p.Board.Node=(uint)original.SpotList[0].SpotId;p.Board.Next=(uint)goal.SpotId;p.Board.Move=1;p.Board.Status=BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_MOVE_WAIT;
                var reward=await peer.Request<GsMovePawnBattleBoardOk>(GameServerCommand.GS_MOVE_PAWN_BATTLE_BOARD_REQUEST,new GsMovePawnBattleBoardRequest{keyInfo=peer.Key,spotId=p.Board.Next});Check(p.Board.Completed.Contains((uint)original.Id)&&reward.rewardCardList.Count+reward.rewardItemList.Count>0,"Original first-clear reward on map "+original.Id);
            }
            p.Board.DefaultPoints=0;uint pointsBefore=p.Missions.DicePoints;CreateCastState();await peer.Request<GsCastDiceBattleBoardOk>(GameServerCommand.GS_CAST_DICE_BATTLE_BOARD_REQUEST,new GsCastDiceBattleBoardRequest{keyInfo=peer.Key});Check(p.Missions.DicePoints==pointsBefore-100,"Earned mission points are actually spent when daily points are empty");
            void CreateCastState(){p.Board.Status=BATTLE_BOARD_STATUS.BATTLE_BOARD_STATUS_DICE_WAIT;p.Board.Node=(uint)catalog.Boards.Single(x=>x.Id==p.Board.Map).SpotList[0].SpotId;p.Board.Next=(uint)catalog.Boards.Single(x=>x.Id==p.Board.Map).SpotList[0].FirstNextSpotId;p.Board.Move=0;}
            p.VipExp=(uint)server.Catalog.Vip.Single(x=>x.VipLv==2).LvUpNeedVipExp;p.CashPoint=1000000;uint diamonds=p.CashPoint,earned=p.Missions.DicePoints;
            var buy=new GsBuyBonusCountRequest{keyInfo=peer.Key,priceType=BscTable.VIP_PRICE_DISCOUNT_TYPE.VIP_PRICE_DISCOUNT_BUY_BATTLE_BOARD_DICE_POINT,buyCount=200};await peer.Request<GsBuyBonusCountOk>(GameServerCommand.GS_BUY_BONUS_COUNT_REQUEST,buy);Check(p.CashPoint==diamonds-19&&p.Missions.DicePoints==earned+200&&p.Board.Bought==200,"Native two-cast purchase costs the original discounted 19 diamonds");string boughtState=State();await peer.Request<GsBuyBonusCountOk>(GameServerCommand.GS_BUY_BONUS_COUNT_REQUEST,buy,retry:true);Check(boughtState==State(),"Dice purchase retry grants once");p.VipExp=0;
            uint balance=p.Missions.DicePoints;await peer.Request<GsResetBattleBoardPlayInfoOk>(GameServerCommand.GS_RESET_BATTLE_BOARD_PLAY_INFO_REQUEST,new GsResetBattleBoardPlayInfoRequest{keyInfo=peer.Key});Check(p.Board.Resets==1&&p.Missions.DicePoints==balance,"Daily reset preserves earned balance");await Bad(GameServerCommand.GS_RESET_BATTLE_BOARD_PLAY_INFO_REQUEST,new GsResetBattleBoardPlayInfoRequest{keyInfo=peer.Key},"Reset limit");
            var usage=await peer.Request<GsResourceStageGetUseCountOk>(GameServerCommand.GS_RESOURCE_STAGE_GET_USE_COUNT_REQUEST,new GsResourceStageGetUseCountRequest{keyInfo=peer.Key});Check(usage.useCount.Count==8&&usage.useCount.All(x=>x.useCount==0),"All original resource stages have initialized counters");
            foreach(var element in catalog.Resources.Where(x=>x.DungeonType==BscTable.RESOURCE_DUNGEON_TYPE.DUNGEON_SOKSUNG))for(int difficulty=0;difficulty<6;difficulty++)Check(catalog.Waves[difficulty].Any(x=>x.Id==element.Id)&&catalog.Rewards[difficulty].Any(x=>x.StageId==element.Id),"Original resource wave/reward table for stage "+element.Id+" difficulty "+difficulty);
            ulong Monday=(ulong)new DateTimeOffset(2026,10,26,12,0,0,TimeSpan.FromHours(8)).ToUnixTimeSeconds();Check(ProtocolRouter.ResourceSchedule(catalog.Resources.Single(x=>x.Id==5),Monday)&&!ProtocolRouter.ResourceSchedule(catalog.Resources.Single(x=>x.Id==4),Monday),"Weekday openings follow original server-local calendar");
            var row=catalog.Resources.First(x=>x.DungeonType==BscTable.RESOURCE_DUNGEON_TYPE.DUNGEON_SOKSUNG&&ProtocolRouter.ResourceSchedule(x,ProtocolRouter.Now));uint stage=(uint)row.Id;
            GsResourceStageBattleStartRequest Start()=>new(){keyInfo=peer.Key,stageid=stage,difficulty=0,deckid=(uint)row.UseDeck};
            var wrong=Start();wrong.deckid=1;await Bad(GameServerCommand.GS_RESOURCE_STAGE_BATTLE_START_REQUEST,wrong,"Wrong resource deck");
            await Bad(GameServerCommand.GS_RESOURCE_STAGE_SKIP_REQUEST,new GsResourceStageSkipRequest{keyInfo=peer.Key,stageId=stage,difficulty=0,skipCount=1},"Sweep before victory");
            uint stamina=p.Stamina;var start=Start();var started=await peer.Request<GsResourceStageBattleStartOk>(GameServerCommand.GS_RESOURCE_STAGE_BATTLE_START_REQUEST,start);Check(started.waveProbIdList.Count>0&&p.Stamina==stamina-10&&p.Resources.Used[stage]==1,"Resource start charges once and selects original waves");string snapshot=State();await peer.Request<GsResourceStageBattleStartOk>(GameServerCommand.GS_RESOURCE_STAGE_BATTLE_START_REQUEST,start,retry:true);Check(snapshot==State(),"Resource start retry is idempotent");
            var ended=new GsResourceStageBattleEndConfirmRequest{keyInfo=peer.Key,stageId=stage,difficulty=0,timeStamp=started.timeStamp,endType=NormalBattleEndType.NORMAL_BATTLE_SUCCESS,enemyAliveCount=unchecked((uint)((started.timeStamp%1000)*stage)),battleEndSyncData=new()};ended.timeStamp++;await Bad(GameServerCommand.GS_RESOURCE_STAGE_BATTLE_END_CONFIRM_REQUEST,ended,"Wrong resource battle stamp");ended.timeStamp--;
            ended.enemyAliveCount++;await Bad(GameServerCommand.GS_RESOURCE_STAGE_BATTLE_END_CONFIRM_REQUEST,ended,"Victory with a surviving enemy");ended.enemyAliveCount--;
            var rewards=await peer.Request<GsResourceStageBattleEndConfirmOk>(GameServerCommand.GS_RESOURCE_STAGE_BATTLE_END_CONFIRM_REQUEST,ended);Check(p.Resources.Cleared.Contains(stage*10)&&p.ActiveStage==null&&rewards.earnedItemList.Count>0,"Victory applies original drops and unlocks sweep");snapshot=State();await peer.Request<GsResourceStageBattleEndConfirmOk>(GameServerCommand.GS_RESOURCE_STAGE_BATTLE_END_CONFIRM_REQUEST,ended,retry:true);Check(snapshot==State(),"Resource result retry grants once");
            var swept=await peer.Request<GsResourceStageSkipOk>(GameServerCommand.GS_RESOURCE_STAGE_SKIP_REQUEST,new GsResourceStageSkipRequest{keyInfo=peer.Key,stageId=stage,difficulty=0,skipCount=2});Check(swept.earnedList.Count==2&&p.Resources.Used[stage]==3&&p.Stamina==stamina-30,"Two sweeps consume exact remaining daily entries");await Bad(GameServerCommand.GS_RESOURCE_STAGE_BATTLE_START_REQUEST,Start(),"Exhausted daily resource entries");
            var resourceReset=new GsMoneyTypeResourceChargeRequest{keyInfo=peer.Key,moneyTypeEvent=BscTable.MONEY_TYPE_EVENT.MONEY_EVENT_RESOURCE_STAGE_RESET_COST,param1=(int)stage};
            await Bad(GameServerCommand.GS_MONEY_TYPE_RESOURCE_CHARGE_REQUEST,resourceReset,"Resource reset respects VIP allowance");
            var b=p.Board;var r=p.Resources;var completed=b.Completed.ToArray();var cleared=r.Cleared.ToArray();ProtocolRouter.RefreshBoardDay(b,500,ProtocolRouter.Now+86400);ProtocolRouter.RefreshResourceDay(r,ProtocolRouter.Now+86400);Check(b.Resets==0&&b.DefaultPoints==500&&p.Missions.DicePoints==balance&&b.Completed.SetEquals(completed)&&r.Used.Count==0&&r.Cleared.SetEquals(cleared),"New day refills daily limits and preserves permanent progress and mission dice");server.Store.Save();
        }
        await using(var reopened=new LocalRuntime(root,save,0,0,0,false)){var p=reopened.Store.All().Single();Check(p.Board.Completed.Count>0&&p.Resources.Cleared.Count>0&&p.Missions.DicePoints>0,"Restart preserves board, resource progress and earned points");}
        File.WriteAllText(Path.Combine(root,"evidence/board-resource-protocol-test.json"),JsonSerializer.Serialize(new{passed=true,checks,productionSaveUsed=false,save},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("BOARD_RESOURCE_TEST_OK "+checks.Count);
    }
}
